-- PRAGMA foreign_keys=OFF;
-- BEGIN TRANSACTION;
CREATE SCHEMA IF NOT EXISTS mn_bids;
USE mn_bids;
CREATE TABLE proposals (
	id INTEGER NOT NULL, 
	proposal_id VARCHAR(50) NOT NULL, 
	description TEXT, 
	source_file VARCHAR(255) NOT NULL, 
	letting_date VARCHAR(100), 
	PRIMARY KEY (id)
);
CREATE TABLE proposal_counties (
	id INTEGER NOT NULL, 
	proposal_id INTEGER NOT NULL, 
	county VARCHAR(100) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(proposal_id) REFERENCES proposals (id)
);
CREATE TABLE bids (
	id INTEGER NOT NULL, 
	proposal_id INTEGER NOT NULL, 
	bidder_name VARCHAR(255) NOT NULL, 
	bid_amount FLOAT NOT NULL, 
	bidder_id VARCHAR(50), 
	comment TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(proposal_id) REFERENCES proposals (id)
);
CREATE UNIQUE INDEX ix_proposals_proposal_id ON proposals (proposal_id);
-- COMMIT;
